def require_backend(ctx: typer.Context) -> Backend:
    """Resolve the backend stored on the Typer context (lazily, once)."""
    obj = ctx.obj
    if isinstance(obj, Backend):
        return obj
    if isinstance(obj, BackendConfig):
        resolved = resolve_backend(obj)
